SELECT  FROM courses
WHERE id IN

    #{item}

SELECT c.id, c.course_id, c.course_name, c.credits, c.teacher_id, c.course_day, c.course_time,
c.course_type, c.major_id, c.academic_year, c.semester, t.name as teacher_name
FROM courses c
LEFT JOIN teachers t ON c.teacher_id = t.id


        AND c.course_name LIKE CONCAT('%', #{courseName}, '%')


        AND t.name LIKE CONCAT('%', #{teacherName}, '%')


        AND c.course_id LIKE CONCAT('%', #{courseId}, '%')


        AND c.major_id = #{majorId}


        AND c.academic_year = #{academicYear}


        AND c.semester = #{semester}


        AND c.course_type = #{courseType}


ORDER BY c.course_id

